class InsufficientFundsException extends Exception {
    private double amount;
    public InsufficientFundsException(double a) {
        super("Insufficient funds: need " + a + " more");
        this.amount = a;
    }
    public double getAmount() { return amount; }
}
class BankAccount {
    double balance;
    BankAccount(double b) { this.balance = b; }
    void withdraw(double amt) throws InsufficientFundsException {
        if (amt > balance)
            throw new InsufficientFundsException(amt - balance);
        balance -= amt;
    }
    public static void main(String[] args) throws InsufficientFundsException {
        BankAccount account = new BankAccount(100.0);
        try {
            account.withdraw(150.0);
        } catch (InsufficientFundsException e) {
            System.out.println(e.getMessage()); // Insufficient funds: need 50.0 more
        }
        account.withdraw(50.0);
        System.out.println("Remaining: " + account.balance); // 50.0
    }
}

