import java.util.*;
public class Main {
    static boolean isBalanced(String s) {
        Deque<Character> st = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            if ("([{".indexOf(c) >= 0) st.push(c);
            else {
                if (st.isEmpty()) return false;
                char top = st.pop();
                if ((c==')' && top!='(') || (c==']' && top!='[') || (c=='}' && top!='{')) return false;
            }
        }
        return st.isEmpty();
    }
    public static void main(String[] args) {
        System.out.println(isBalanced("([{}])")); // true
        System.out.println(isBalanced("([)]"));   // false
        System.out.println(isBalanced("{[]}"));   // true
    }
}

class BST {
    int val; BST left, right;
    BST(int v) { val = v; }
    BST insert(int v) {
        if (v < val) left  = (left  == null) ? new BST(v) : left.insert(v);
        else         right = (right == null) ? new BST(v) : right.insert(v);
        return this;
    }
    void inOrder() { if (left!=null) left.inOrder(); System.out.print(val+" "); if (right!=null) right.inOrder(); }
    public static void main(String[] args) {
        BST tree = new BST(5);
        tree.insert(3); tree.insert(7); tree.insert(1); tree.insert(4);
        tree.inOrder(); // 1 3 4 5 7
        System.out.println();
    }
}

