import java.util.Arrays;
public class Main {
    static void mergeSort(int[] arr, int l, int r) {
        if (l >= r) return;
        int m = (l+r)/2;
        mergeSort(arr, l, m);
        mergeSort(arr, m+1, r);
        merge(arr, l, m, r);
    }
    static void merge(int[] arr, int l, int m, int r) {
        int[] tmp = Arrays.copyOfRange(arr, l, r+1);
        int i=0, j=m-l+1, k=l;
        while (i<=m-l && j<=r-l) arr[k++] = tmp[i]<=tmp[j] ? tmp[i++] : tmp[j++];
        while (i<=m-l) arr[k++] = tmp[i++];
        while (j<=r-l) arr[k++] = tmp[j++];
    }
    public static void main(String[] args) {
        int[] arr = {5, 3, 8, 1, 2};
        mergeSort(arr, 0, arr.length-1);
        System.out.println(Arrays.toString(arr)); // [1, 2, 3, 5, 8]
    }
}

public class Main {
    static int firstOccurrence(int[] arr, int target) {
        int lo=0, hi=arr.length-1, result=-1;
        while (lo<=hi) {
            int mid=(lo+hi)/2;
            if (arr[mid]==target) { result=mid; hi=mid-1; } // keep searching left
            else if (arr[mid]<target) lo=mid+1;
            else hi=mid-1;
        }
        return result;
    }
    public static void main(String[] args) {
        int[] arr = {1, 2, 2, 2, 3, 4};
        System.out.println(firstOccurrence(arr, 2)); // 1
        System.out.println(firstOccurrence(arr, 5)); // -1
    }
}

import java.util.*;
public class Main {
    public static void main(String[] args) {
        List<String> list = new ArrayList<>(Arrays.asList("Anna","Bob","Alice","Charlie","Amy"));
        int n = list.size();
        List<String> result = new ArrayList<>();

        // O(n) — single loop
        for (String s : list) System.out.print(s + " ");
        System.out.println();

        // O(n²) — nested loops over same collection
        for (int i=0;i<n;i++) for (int j=0;j<n;j++) { /* check pair (i,j) */ }

        // O(n log n) — sort then linear scan
        Collections.sort(list);
        for (String s : list) if (s.startsWith("A")) result.add(s);
        System.out.println(result); // [Alice, Amy, Anna]
    }
}

import java.util.*;
public class Main {
    static void subsets(int[] nums, int start, List<Integer> cur, List<List<Integer>> res) {
        res.add(new ArrayList<>(cur));
        for (int i=start; i<nums.length; i++) {
            cur.add(nums[i]);
            subsets(nums, i+1, cur, res);
            cur.remove(cur.size()-1); // undo
        }
    }
    public static void main(String[] args) {
        int[] nums = {1, 2, 3};
        List<List<Integer>> res = new ArrayList<>();
        subsets(nums, 0, new ArrayList<>(), res);
        System.out.println(res);
        // [[], [1], [1, 2], [1, 2, 3], [1, 3], [2], [2, 3], [3]]
    }
}

import java.util.*;
public class Main {
    static class User {
        int id; String name;
        User(int id, String name) { this.id=id; this.name=name; }
    }
    static List<User> users = Arrays.asList(
        new User(1,"Alice"), new User(42,"Bob"), new User(99,"Charlie"));

    static Optional<User> findById(int id) {
        return users.stream()
            .filter(u -> u.id == id)
            .findFirst();
    }
    public static void main(String[] args) {
        findById(42).ifPresent(u -> System.out.println("Found: " + u.name)); // Found: Bob
        System.out.println(findById(0).isPresent()); // false
    }
}
